} }];

const data = $input.first().json;
const hermes = $('hermes 분석 API').item.json;
const wp_comment = hermes.wp_comment || '';
const nas_refs = hermes.nas_refs || [];

let comment_body = wp_comment;
if (!comment_body) {
  // hermes wp_comment 없으면 기본 포맷으로 생성
  const h = data.hermesData || {};
  const priorityIcon = { high: '🔴', medium: '🟡', low: '🟢' }[h.priority] || '🟡';
  const priorityLabel = { high: '높음 — 즉시 대응', medium: '보통', low: '낮음' }[h.priority] || '보통';

  let rows = `| 중요도 | ${priorityIcon} **${priorityLabel}** |\n`;
  if (h.deadline)   rows += `| ⏰ 기한 | **${h.deadline}** |\n`;
  if (h.org)        rows += `| 🏢 발신기관 | ${h.org} |\n`;
  if (h.region)     rows += `| 🌏 대상 지역 | ${h.region} |\n`;
  if (h.task_type)  rows += `| 📋 업무 구분 | ${h.task_type} |\n`;

  let c = `## [Hermes] RA 대응 가이드\n\n`;
  c += `| 항목 | 내용 |\n|---|---|\n${rows}\n`;
  c += `### 즉시 취해야 할 조치\n${h.action || '(원본 메일 확인 후 조치 결정)'}\n\n`;
  if (h.summary) c += `### 업무 요약\n${h.summary}\n\n`;
  if (h.attachments_note) c += `### 관련 문서\n${h.attachments_note}\n\n`;
  if (nas_refs.length > 0) c += `### NAS 참고 파일\n${nas_refs.map(r => `- ${r}`).join('\n')}\n\n`;
  c += `---\n*gemma3:4b 자동 분석 (Hermes v4)*`;
  comment_body = c;
}

return [{ json: { ...data, comment_body, commentBody: JSON.stringify({ comment: { raw: comment_body } }) } }];

