const glmAnalysis = $('GLM 분석 (Zhipu AI)')[0].json || {};
const codexAnalysis = $('Codex 분석 (GPT-4)')[0].json || {};
const copilotAnalysis = $('Copilot 분석 (Claude)')[0].json || {};

// 각 모델의 응답 텍스트 추출
const glmText = glmAnalysis.choices?.[0]?.message?.content || '(응답 없음)';
const codexText = codexAnalysis.choices?.[0]?.message?.content || '(응답 없음)';
const copilotText = copilotAnalysis.choices?.[0]?.message?.content || '(응답 없음)';

// 토큰 사용량
const glmTokens = glmAnalysis.usage || {};
const codexTokens = codexAnalysis.usage || {};
const copilotTokens = copilotAnalysis.usage || {};

return {
  ...JSON.parse(JSON.stringify($input.item.json)),
  modelResults: {
    glm: {
      model: 'GLM (Zhipu AI)',
      content: glmText,
      inputTokens: glmTokens.prompt_tokens || 0,
      outputTokens: glmTokens.completion_tokens || 0,
      totalTokens: glmTokens.total_tokens || 0
    },
    codex: {
      model: 'Codex (ChatGPT Pro)',
      content: codexText,
      inputTokens: codexTokens.prompt_tokens || 0,
      outputTokens: codexTokens.completion_tokens || 0,
      totalTokens: codexTokens.total_tokens || 0
    },
    copilot: {
      model: 'Copilot (Copilot Pro)',
      content: copilotText,
      inputTokens: copilotTokens.prompt_tokens || 0,
      outputTokens: copilotTokens.completion_tokens || 0,
      totalTokens: copilotTokens.total_tokens || 0
    }
  }
};

const models = $json.modelResults;
const wpId = $json.createdWpId;

const comments = [];

// GLM 댓글
comments.push({
  wpId: wpId,
  author: 'Hermes Agent',
  model: 'GLM (Zhipu AI)',
  content: `🤖 **GLM 분석 결과**

${models.glm.content}

📊 성능:
- 입력 토큰: ${models.glm.inputTokens}
- 출력 토큰: ${models.glm.outputTokens}
- 총 토큰: ${models.glm.totalTokens}`
});

// Codex 댓글
comments.push({
  wpId: wpId,
  author: 'Hermes Agent',
  model: 'Codex (ChatGPT Pro)',
  content: `🤖 **Codex 분석 결과**

${models.codex.content}

📊 성능:
- 입력 토큰: ${models.codex.inputTokens}
- 출력 토큰: ${models.codex.outputTokens}
- 총 토큰: ${models.codex.totalTokens}`
});

// Copilot 댓글
comments.push({
  wpId: wpId,
  author: 'Hermes Agent',
  model: 'Copilot (Copilot Pro)',
  content: `🤖 **Copilot 분석 결과**

${models.copilot.content}

📊 성능:
- 입력 토큰: ${models.copilot.inputTokens}
- 출력 토큰: ${models.copilot.outputTokens}
- 총 토큰: ${models.copilot.totalTokens}`
});

return { comments, wpId, ...JSON.parse(JSON.stringify($input.item.json)) };
